  if (error instanceof CorruptCheckpointError) {
    // Keep the damaged file as evidence. Restarting from line 0 is safe because
    // the output identities below suppress anything already written.
    quarantinedCheckpoint = `${checkpointPath}.corrupt-${new Date().toISOString().replace(/[:.]/g, '-')}`;
